package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_countriesByLanguage_TriageGen2Test {

    @Test
    public void testCountriesByLanguage_NullLanguageCode() {
        List<Locale> result = LocaleUtils.countriesByLanguage(null);
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_ExistingLanguageCode() {
        // Test with a known language code that exists in availableLocaleList
        // This tests the branch where countries is not null (retrieved from cache)
        // Note: Due to static caching in the real class, we call it twice to ensure cache coverage
        List<Locale> result1 = LocaleUtils.countriesByLanguage("en");
        List<Locale> result2 = LocaleUtils.countriesByLanguage("en");

        assertNotNull(result1);
        assertSame(result1, result2); // Verify it returns the cached list
    }

    @Test
    public void testCountriesByLanguage_NewLanguageCode_WithMatches() {
        // Test a language that likely has countries (e.g., "en" or "fr")
        // This covers the logic: countries == null -> loop through locales -> match language, country length > 0, variant empty
        List<Locale> result = LocaleUtils.countriesByLanguage("en");

        assertNotNull(result);
        for (Locale locale : result) {
            assertEquals("en", locale.getLanguage());
            assertNotEquals("", locale.getCountry());
            assertEquals("", locale.getVariant());
        }
    }

    @Test
    public void testCountriesByLanguage_NewLanguageCode_NoMatches() {
        // Test a language code that is unlikely to exist in the system
        // This covers the branch where the loop completes but no locales are added
        List<Locale> result = LocaleUtils.countriesByLanguage("zz");

        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_FilteringLogic() {
        // This test targets the specific conditions in the if statement:
        // 1. languageCode.equals(locale.getLanguage())
        // 2. locale.getCountry().length() != 0
        // 3. locale.getVariant().isEmpty()

        // We use a language that is known to have various locale configurations
        List<Locale> result = LocaleUtils.countriesByLanguage("en");

        for (Locale locale : result) {
            assertTrue("Language must match", locale.getLanguage().equals("en"));
            assertTrue("Country must not be empty", locale.getCountry().length() > 0);
            assertTrue("Variant must be empty", locale.getVariant().isEmpty());
        }
    }
}
